  private void zzScanError(int errorCode) {
    String message;
    try {
      message = ZZ_ERROR_MSG[errorCode];
    }
    catch (ArrayIndexOutOfBoundsException e) {
      message = ZZ_ERROR_MSG[ZZ_UNKNOWN_ERROR];
    }

    throw new Error(message);
  }


  /**
   * Pushes the specified amount of characters back into the input stream.
   *
   * They will be read again by then next call of the scanning method
   *
   * @param number  the number of characters to be read again.
   *                This number must not be greater than yylength()!
   */
  public void yypushback(int number)  {
    if ( number > yylength() )
      zzScanError(ZZ_PUSHBACK_2BIG);

    zzMarkedPos -= number;
  }


  /**
   * Contains user EOF-code, which will be executed exactly once,
   * when the end of file is reached
   */
  private void zzDoEOF() {
    if (!zzEOFDone) {
      zzEOFDone = true;
    
    }
  }


  /**
   * Resumes scanning until the next regular expression is matched,
   * the end of input is encountered or an I/O-Error occurs.
   *
   * @return      the next token
   * @exception   java.io.IOException  if any I/O-Error occurs
   */
  public IElementType advance() throws java.io.IOException
  {
    int zzInput;
    int zzAction;

    // cached fields:
    int zzCurrentPosL;
    int zzMarkedPosL;
    int zzEndReadL = zzEndRead;
    CharSequence zzBufferL = zzBuffer;

    int [] zzTransL = ZZ_TRANS;
    int [] zzRowMapL = ZZ_ROWMAP;
    int [] zzAttrL = ZZ_ATTRIBUTE;

    while (true) {
      zzMarkedPosL = zzMarkedPos;

      zzAction = -1;

      zzCurrentPosL = zzCurrentPos = zzStartRead = zzMarkedPosL;

      zzState = ZZ_LEXSTATE[zzLexicalState];

      // set up zzAction for empty match case:
      int zzAttributes = zzAttrL[zzState];
      if ( (zzAttributes & 1) == 1 ) {
        zzAction = zzState;
      }


      zzForAction: {
        while (true) {

          if (zzCurrentPosL < zzEndReadL) {
            zzInput = Character.codePointAt(zzBufferL, zzCurrentPosL);
            zzCurrentPosL += Character.charCount(zzInput);
          }
          else if (zzAtEOF) {
            zzInput = YYEOF;
            break zzForAction;
          }
          else {
            // store back cached positions
            zzCurrentPos  = zzCurrentPosL;
            zzMarkedPos   = zzMarkedPosL;
            boolean eof = zzRefill();
            // get translated positions and possibly new buffer
            zzCurrentPosL  = zzCurrentPos;
            zzMarkedPosL   = zzMarkedPos;
            zzBufferL      = zzBuffer;
            zzEndReadL     = zzEndRead;
            if (eof) {
              zzInput = YYEOF;
              break zzForAction;
            }
            else {
              zzInput = Character.codePointAt(zzBufferL, zzCurrentPosL);
              zzCurrentPosL += Character.charCount(zzInput);
            }
          }
          int zzNext = zzTransL[ zzRowMapL[zzState] + zzCMap(zzInput) ];
          if (zzNext == -1) break zzForAction;
          zzState = zzNext;

          zzAttributes = zzAttrL[zzState];
          if ( (zzAttributes & 1) == 1 ) {
            zzAction = zzState;
            zzMarkedPosL = zzCurrentPosL;
            if ( (zzAttributes & 8) == 8 ) break zzForAction;
          }

        }
      }

      // store back cached position
      zzMarkedPos = zzMarkedPosL;

      if (zzInput == YYEOF && zzStartRead == zzCurrentPos) {
        zzAtEOF = true;
            zzDoEOF();
        return null;
      }
      else {
        switch (zzAction < 0 ? zzAction : ZZ_ACTION[zzAction]) {
          case 1:
            { return TokenType.BAD_CHARACTER;
            }
          // fall through
          case 32: break;
          case 2:
            { return TokenType.WHITE_SPACE;
            }
          // fall through
          case 33: break;
          case 3:
            { return PrismioTypes.COMPARISON;
            }
          // fall through
          case 34: break;
          case 4:
            { return PrismioTypes.ARITHMETIC_OP;
            }
          // fall through
          case 35: break;
          case 5:
            { return PrismioTypes.BITWISE;
            }
          // fall through
          case 36: break;
          case 6:
            { return PrismioTypes.LPAREN;
            }
          // fall through
          case 37: break;
          case 7:
            { return PrismioTypes.RPAREN;
            }
          // fall through
          case 38: break;
          case 8:
            { return PrismioTypes.COMMA;
            }
          // fall through
          case 39: break;
          case 9:
            { return PrismioTypes.DOT;
            }
          // fall through
          case 40: break;
          case 10:
            { return PrismioTypes.INTEGER;
            }
          // fall through
          case 41: break;
          case 11:
            { return PrismioTypes.COLON;
            }
          // fall through
          case 42: break;
          case 12:
            { return PrismioTypes.SEMICOLON;
            }
          // fall through
          case 43: break;
          case 13:
            { return PrismioTypes.IDENTIFIER;
            }
          // fall through
          case 44: break;
          case 14:
            { return PrismioTypes.LBRACKET;
            }
          // fall through
          case 45: break;
          case 15:
            { return PrismioTypes.RBRACKET;
            }
          // fall through
          case 46: break;
          case 16:
            { return PrismioTypes.LBRACE;
            }
          // fall through
          case 47: break;
          case 17:
            { return PrismioTypes.RBRACE;
            }
          // fall through
          case 48: break;
          case 18:
            { return PrismioTypes.RELATIONAL_OP;
            }
          // fall through
          case 49: break;
          case 19:
            { return PrismioTypes.STRING_LITERAL;
            }
          // fall through
          case 50: break;
          case 20:
            { return PrismioTypes.ASSIGNMENT_OP;
            }
          // fall through
          case 51: break;
          case 21:
            { return PrismioTypes.LOGICAL_OP;
            }
          // fall through
          case 52: break;
          case 22:
            { return PrismioTypes.UNARY_OP;
            }
          // fall through
          case 53: break;
          case 23:
            { return PrismioTypes.ARROW;
            }
          // fall through
          case 54: break;
          case 24:
            { return PrismioTypes.FLOAT;
            }
          // fall through
          case 55: break;
          case 25:
            { return PrismioTypes.SINGLE_LINE_COMMENT;
            }
          // fall through
          case 56: break;
          case 26:
            { return PrismioTypes.FAT_ARROW;
            }
          // fall through
          case 57: break;
          case 27:
            { return PrismioTypes.KEYWORD;
            }
          // fall through
          case 58: break;
          case 28:
            { return PrismioTypes.CHARACTER_LITERAL;
            }
          // fall through
          case 59: break;
          case 29:
            { return PrismioTypes.TYPE_KEYWORD;
            }
          // fall through
          case 60: break;
          case 30:
            { return PrismioTypes.MULTILINE_COMMENT;
            }
          // fall through
          case 61: break;
          case 31:
            { return PrismioTypes.BOOLEAN;
            }
          // fall through
          case 62: break;
          default:
            zzScanError(ZZ_NO_MATCH);
          }
      }
    }
  }


